insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('4f12fe1b-3d12-54a6-8945-7f8756572115', 'ce720323-3385-5775-ae79-602fb3ae15a9', 9, 'tekst', '{"tekst": "De werknemers waarvoor dit handboek is bestemd hebben 2 verschillende CAO’s, de cao Bouw & Infra en de SAVG CAO. Bij sommige onderwerpen is verschillende regelgeving van kracht. We hebben in dat geval afspraken gehanteerd die het meest overeenkomen met de huidige gang van zaken of die het gunstigste zijn voor zowel werknemer en werkgever."}'::jsonb, 'De werknemers waarvoor dit handboek is bestemd hebben 2 verschillende CAO’s, de cao Bouw & Infra en de SAVG CAO. Bij sommige onderwerpen is verschillende regelgeving van kracht. We hebben in dat geval afspraken gehanteerd die het meest overeenkomen met de huidige gang van zaken of die het gunstigste zijn voor zowel werknemer en werkgever.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_secties (id, slug, titel, volgorde, soort, status, zichtbaar_voor, verborgen_voor) values ('229be932-8cda-5792-b85a-ea4dfadfe17a', 'je-collegas', 'Je collega’s', 2, 'hoofdstuk', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('f76b2667-7473-554d-88db-dc918b4a4d25', '229be932-8cda-5792-b85a-ea4dfadfe17a', 1, 'tekst', '{"tekst": "Samenwerken met collega''s vormt het kloppende hart van onze organisatie."}'::jsonb, 'Samenwerken met collega''s vormt het kloppende hart van onze organisatie.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('4f1c139d-3460-54c2-8812-d01ba62b4576', '229be932-8cda-5792-b85a-ea4dfadfe17a', 2, 'tekst', '{"tekst": "Wij geloven in de kracht van één team, één taak gezamenlijk doel voor ogen."}'::jsonb, 'Wij geloven in de kracht van één team, één taak gezamenlijk doel voor ogen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('62a6afb7-6a81-5a94-b749-09df8f29bb95', '229be932-8cda-5792-b85a-ea4dfadfe17a', 3, 'tekst', '{"tekst": "In deze samenwerking ontstaan niet alleen buitengewone prestaties, maar ook een stimulerende en positieve werkomgeving."}'::jsonb, 'In deze samenwerking ontstaan niet alleen buitengewone prestaties, maar ook een stimulerende en positieve werkomgeving.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('649eea97-6d9a-5bb1-b6e6-56622ef603ba', '229be932-8cda-5792-b85a-ea4dfadfe17a', 4, 'tekst', '{"tekst": "Bij Everts erkennen we de waarde van elk teamlid en het unieke perspectief dat iedereen met zich meebrengt. We koesteren diversiteit en geloven dat het bundelen van onze verschillende talenten en ervaringen de sleutel is tot innovatie en groei."}'::jsonb, 'Bij Everts erkennen we de waarde van elk teamlid en het unieke perspectief dat iedereen met zich meebrengt. We koesteren diversiteit en geloven dat het bundelen van onze verschillende talenten en ervaringen de sleutel is tot innovatie en groei.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('907eab1a-0293-5bfb-b488-bb08b376c7cc', '229be932-8cda-5792-b85a-ea4dfadfe17a', 5, 'tekst', '{"tekst": "Het creëren van een open communicatiecultuur staat centraal in onze samenwerking. We moedigen onze teamleden aan om ideeën te delen, vragen te stellen en feedback te geven. Op deze manier bouwen we samen aan een omgeving waarin iedereen wordt aangemoedigd om bij te dragen aan het succes van het team."}'::jsonb, 'Het creëren van een open communicatiecultuur staat centraal in onze samenwerking. We moedigen onze teamleden aan om ideeën te delen, vragen te stellen en feedback te geven. Op deze manier bouwen we samen aan een omgeving waarin iedereen wordt aangemoedigd om bij te dragen aan het succes van het team.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('e0a944af-c644-5a43-a25f-2392ce5e78ad', '229be932-8cda-5792-b85a-ea4dfadfe17a', 6, 'tekst', '{"tekst": "Bij Everts geloven we ook in het ondersteunen van elkaar. Samenwerken betekent niet alleen gezamenlijk doelen nastreven, maar ook het bieden van hulp wanneer dat nodig is."}'::jsonb, 'Bij Everts geloven we ook in het ondersteunen van elkaar. Samenwerken betekent niet alleen gezamenlijk doelen nastreven, maar ook het bieden van hulp wanneer dat nodig is.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('f1586f23-bc36-5036-b5bf-67662aee539e', '229be932-8cda-5792-b85a-ea4dfadfe17a', 7, 'tekst', '{"tekst": "We begrijpen dat we sterker zijn wanneer we elkaars sterke punten erkennen en elkaars zwakke punten ondersteunen."}'::jsonb, 'We begrijpen dat we sterker zijn wanneer we elkaars sterke punten erkennen en elkaars zwakke punten ondersteunen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('d92357e3-f251-54d7-aa6f-0f7dc5f3f646', '229be932-8cda-5792-b85a-ea4dfadfe17a', 8, 'tekst', '{"tekst": "Samenwerken is niet alleen een onderdeel van wat we doen, het is wie we zijn. Laten we blijven streven naar het allerbeste en samen groeien in een omgeving waarin iedereen kan schitteren."}'::jsonb, 'Samenwerken is niet alleen een onderdeel van wat we doen, het is wie we zijn. Laten we blijven streven naar het allerbeste en samen groeien in een omgeving waarin iedereen kan schitteren.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('3dc9c690-748d-5553-a8df-50a49fe15bd2', '229be932-8cda-5792-b85a-ea4dfadfe17a', 9, 'tekst', '{"tekst": "Daarnaast geloven we sterk in het vieren van successen, groot en klein. Het is belangrijk om samen te genieten van onze prestaties en te erkennen dat elke bijdrage waardevol is voor het team. Op deze manier creëren we een positieve en inspirerende sfeer waarin iedereen zich gewaardeerd voelt."}'::jsonb, 'Daarnaast geloven we sterk in het vieren van successen, groot en klein. Het is belangrijk om samen te genieten van onze prestaties en te erkennen dat elke bijdrage waardevol is voor het team. Op deze manier creëren we een positieve en inspirerende sfeer waarin iedereen zich gewaardeerd voelt.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('fd14a2c2-3ebf-5604-bd54-d55cea773ef4', '229be932-8cda-5792-b85a-ea4dfadfe17a', 10, 'tekst', '{"tekst": "Laten we blijven streven naar groei, innovatie en uitmuntendheid. Samen vormen we de drijvende kracht achter onze successen en laten we een blijvende indruk achter in alles wat we doen."}'::jsonb, 'Laten we blijven streven naar groei, innovatie en uitmuntendheid. Samen vormen we de drijvende kracht achter onze successen en laten we een blijvende indruk achter in alles wat we doen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('54cc6160-6c69-5ab2-ae16-e87f2099bae0', '229be932-8cda-5792-b85a-ea4dfadfe17a', 11, 'tekst', '{"tekst": "Dus laten we elke dag benaderen met een positieve houding, met respect voor elkaars instelling en met de vastberadenheid om samen te beter te worden."}'::jsonb, 'Dus laten we elke dag benaderen met een positieve houding, met respect voor elkaars instelling en met de vastberadenheid om samen te beter te worden.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_secties (id, slug, titel, volgorde, soort, status, zichtbaar_voor, verborgen_voor) values ('c5baa818-382c-5b5f-8c9c-bd4001a0e005', 'personeelsvereniging', 'Personeelsvereniging', 3, 'hoofdstuk', 'gepubliceerd', '{}', array['extern']::text[]) on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('f9cb6f77-da01-52c4-a238-0f62170c73e3', 'c5baa818-382c-5b5f-8c9c-bd4001a0e005', 1, 'tekst', '{"tekst": "Een personeelsvereniging (afgekort tot PV) is een vereniging waarvan alleen het personeel lid kan worden. De vereniging is vooral bedoeld om de successen te vieren en elkaar beter te leren kennen. Zij organiseert daarom een personeelsuitstapje, zomerfeest, kerstfeest, brengt een bloemetje bij langdurig zieken, besteedt aandacht aan jubilea enz."}'::jsonb, 'Een personeelsvereniging (afgekort tot PV) is een vereniging waarvan alleen het personeel lid kan worden. De vereniging is vooral bedoeld om de successen te vieren en elkaar beter te leren kennen. Zij organiseert daarom een personeelsuitstapje, zomerfeest, kerstfeest, brengt een bloemetje bij langdurig zieken, besteedt aandacht aan jubilea enz.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('b087c2d2-0fdb-52ec-af09-f6b54318be63', 'c5baa818-382c-5b5f-8c9c-bd4001a0e005', 2, 'tekst', '{"tekst": "De jaarlijkse contributie is 13 periodes x € 7,50 per lid. Dit wordt van het salaris ingehouden. Everts legt dezelfde bijdrage in per personeelslid."}'::jsonb, 'De jaarlijkse contributie is 13 periodes x € 7,50 per lid. Dit wordt van het salaris ingehouden. Everts legt dezelfde bijdrage in per personeelslid.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('7a95343d-e72a-517d-be42-1585f3139c51', 'c5baa818-382c-5b5f-8c9c-bd4001a0e005', 3, 'tekst', '{"tekst": "De PV wordt geleidt door  vrijwilligers die zich hiervoor hebben aangemeld of hiervoor zijn gevraagd."}'::jsonb, 'De PV wordt geleidt door  vrijwilligers die zich hiervoor hebben aangemeld of hiervoor zijn gevraagd.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('1efce819-a380-53fa-b549-deb1e0f241c7', 'c5baa818-382c-5b5f-8c9c-bd4001a0e005', 4, 'tekst', '{"tekst": "Het verenigingsbestuur is verplicht ieder jaar een jaarvergadering te houden. Hier wordt verantwoording afgelegd aan de leden."}'::jsonb, 'Het verenigingsbestuur is verplicht ieder jaar een jaarvergadering te houden. Hier wordt verantwoording afgelegd aan de leden.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
