insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('c309c223-1df1-5514-97d0-54b38d6914be', '521bfe48-de71-542c-b505-0de67d366abf', 3, 'tabel', '{"kolommen": [], "rijen": [["-", "het correct gekleed gaan;"], ["-", "correct, niet provocerend gedrag"], ["-", "stiptheid en zorgvuldigheid bij het afhandelen van opdrachten"], ["-", "het op kantoor indienen van verbeteringsvoorstellen ten behoeve van service aan klanten"], ["-", "het netjes achterlaten van de werkplek, bedrijfsterreinen, kantines en sanitaire voorzieningen"], ["-", "deskundige omgang met materieel"], ["-", "het melden van klachten en opmerkingen van klanten"], ["-", "het melden van ongevallen en bijna-ongevallen"]]}'::jsonb, '- het correct gekleed gaan; - correct, niet provocerend gedrag - stiptheid en zorgvuldigheid bij het afhandelen van opdrachten - het op kantoor indienen van verbeteringsvoorstellen ten behoeve van service aan klanten - het netjes achterlaten van de werkplek, bedrijfsterreinen, kantines en sanitaire voorzieningen - deskundige omgang met materieel - het melden van klachten en opmerkingen van klanten - het melden van ongevallen en bijna-ongevallen', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('3c323a85-4390-55e4-afd7-6fe9718dbfe9', '521bfe48-de71-542c-b505-0de67d366abf', 4, 'tekst', '{"tekst": "U dient op eigen gelegenheid en buiten werktijd naar het werk te gaan waar u werkzaam bent of zult zijn, tenzij anders overeengekomen."}'::jsonb, 'U dient op eigen gelegenheid en buiten werktijd naar het werk te gaan waar u werkzaam bent of zult zijn, tenzij anders overeengekomen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('dea7e038-4f5a-56d4-b072-96077d522eb4', '521bfe48-de71-542c-b505-0de67d366abf', 5, 'tekst', '{"tekst": "Het is niet toegestaan om tijdens uw werk alcohol te drinken en/of drugs te gebruiken. Ook niet als de klant het u aanbiedt. U dient geheel nuchter en niet gedrogeerd op uw werkplek te verschijnen. Indien wordt geconstateerd dat u niet nuchter bent of gedrogeerd bent, zal de toegang tot het werk geweigerd worden. Met andere woorden, u wordt onmiddellijk van het werk verwijderd."}'::jsonb, 'Het is niet toegestaan om tijdens uw werk alcohol te drinken en/of drugs te gebruiken. Ook niet als de klant het u aanbiedt. U dient geheel nuchter en niet gedrogeerd op uw werkplek te verschijnen. Indien wordt geconstateerd dat u niet nuchter bent of gedrogeerd bent, zal de toegang tot het werk geweigerd worden. Met andere woorden, u wordt onmiddellijk van het werk verwijderd.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('3f2711d4-483a-558b-9253-90fbdf9a411c', '521bfe48-de71-542c-b505-0de67d366abf', 6, 'tekst', '{"tekst": "Een officiële waarschuwing zal in het personeelsdossier worden opgenomen."}'::jsonb, 'Een officiële waarschuwing zal in het personeelsdossier worden opgenomen.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('1e25f033-cf71-56ee-93a5-b5a59b520a17', '521bfe48-de71-542c-b505-0de67d366abf', 7, 'tekst', '{"tekst": "De loonbetaling zal ook onmiddellijk worden gestopt tot het tijdstip dat u zich nuchter meldt bij uw leidinggevende. De hervatting van loonbetaling gaat altijd pas in bij aanvang van een volgende  werkdag waarop u weer nuchter op het werk verschijnt."}'::jsonb, 'De loonbetaling zal ook onmiddellijk worden gestopt tot het tijdstip dat u zich nuchter meldt bij uw leidinggevende. De hervatting van loonbetaling gaat altijd pas in bij aanvang van een volgende  werkdag waarop u weer nuchter op het werk verschijnt.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('b90b3a6c-3bb1-533d-a2d9-09e55085eb6e', '521bfe48-de71-542c-b505-0de67d366abf', 8, 'tekst', '{"tekst": "Het is niet toegestaan om tijdens uw werk alcohol te drinken en/of drugs te gebruiken. Ook niet als de klant het u aanbiedt. U dient geheel nuchter en niet gedrogeerd op uw werkplek te verschijnen. Indien wordt geconstateerd dat u niet nuchter bent of gedrogeerd bent, zal de toegang tot het werk geweigerd worden. Met andere woorden, u wordt onmiddellijk van het werk verwijderd en uw opdracht wordt per direct stop gezet."}'::jsonb, 'Het is niet toegestaan om tijdens uw werk alcohol te drinken en/of drugs te gebruiken. Ook niet als de klant het u aanbiedt. U dient geheel nuchter en niet gedrogeerd op uw werkplek te verschijnen. Indien wordt geconstateerd dat u niet nuchter bent of gedrogeerd bent, zal de toegang tot het werk geweigerd worden. Met andere woorden, u wordt onmiddellijk van het werk verwijderd en uw opdracht wordt per direct stop gezet.', 'gepubliceerd', array['extern']::text[], '{}') on conflict (id) do nothing;
