insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('73b33d91-85e9-5011-86b8-e97a0871a121', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 2, 'tekst', '{"tekst": "Hiervoor is kennis en zijn diverse vaardigheden vereist."}'::jsonb, 'Hiervoor is kennis en zijn diverse vaardigheden vereist.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('e0abad52-8ad1-5ecd-b056-36e2bfbb1589', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 3, 'tekst', '{"tekst": "Daarom besteedt Everts veel aandacht aan scholing en opleiding voor alle medewerkers door middel van in- en externe opleidingen. Het volgen van een cursus kan op grond van uw functie en veiligheid binnen het bedrijf verplicht worden gesteld, om een zo goed mogelijk veiligheids- en kwaliteitsniveau blijvend te kunnen garanderen."}'::jsonb, 'Daarom besteedt Everts veel aandacht aan scholing en opleiding voor alle medewerkers door middel van in- en externe opleidingen. Het volgen van een cursus kan op grond van uw functie en veiligheid binnen het bedrijf verplicht worden gesteld, om een zo goed mogelijk veiligheids- en kwaliteitsniveau blijvend te kunnen garanderen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('121e21a0-8263-5bdf-9b8b-a970b4f37759', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 4, 'tekst', '{"tekst": "Vanuit milieuwetgeving en kwaliteitseisen worden er steeds meer eisen gesteld. Om ook in de toekomst te kunnen werken volgens de wet- en regelgeving is regelmatige scholing en bijscholing een absolute eis."}'::jsonb, 'Vanuit milieuwetgeving en kwaliteitseisen worden er steeds meer eisen gesteld. Om ook in de toekomst te kunnen werken volgens de wet- en regelgeving is regelmatige scholing en bijscholing een absolute eis.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('1f1ba07b-a9c0-513d-8499-f7134560551a', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 5, 'tekst', '{"tekst": "Everts stelt de medewerkers in de gelegenheid deze opleidingen te volgen. Medewerkers zijn behouden naar beste vermogen deel te nemen aan deze opleidingen, opleidingsactiviteiten, informatie bijeenkomsten en instructie-bijeenkomsten, waartoe de medewerkers worden uitgenodigd."}'::jsonb, 'Everts stelt de medewerkers in de gelegenheid deze opleidingen te volgen. Medewerkers zijn behouden naar beste vermogen deel te nemen aan deze opleidingen, opleidingsactiviteiten, informatie bijeenkomsten en instructie-bijeenkomsten, waartoe de medewerkers worden uitgenodigd.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('44fe300f-c7d3-5e88-96ba-dae972719591', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 6, 'tekst', '{"tekst": "Medewerkers kunnen schriftelijk een verzoek indienen voor het volgen van een opleiding en cursus."}'::jsonb, 'Medewerkers kunnen schriftelijk een verzoek indienen voor het volgen van een opleiding en cursus.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('59885eda-acdf-50ba-b809-20c825afaef1', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 7, 'tekst', '{"tekst": "Studie-, opleidings- en examenkosten worden éénmalig geheel vergoed wanneer de studie met toestemming van de werkgever wordt gevolgd. Bij niet slagen wordt de verplichting tot herhaling en de kosten kwestie beoordeeld door de leidinggevende. Mocht u het dienstverband binnen 3 jaar beëindigen dan gelden de volgende voorwaarden;"}'::jsonb, 'Studie-, opleidings- en examenkosten worden éénmalig geheel vergoed wanneer de studie met toestemming van de werkgever wordt gevolgd. Bij niet slagen wordt de verplichting tot herhaling en de kosten kwestie beoordeeld door de leidinggevende. Mocht u het dienstverband binnen 3 jaar beëindigen dan gelden de volgende voorwaarden;', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('5c95b338-9648-539e-8f0a-4a9c6e2d573d', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 8, 'tekst', '{"tekst": "Indien de studie niet tijdens uw dienstverband met Everts wordt afgemaakt dient u altijd het volledige bedrag aan de werkgever terug te betalen. Indien u elders gaat werken, binnen een periode van 3 jaar na het behalen van het diploma (’s ) dient u eveneens het volledige bedrag aan de werkgever terug te betalen."}'::jsonb, 'Indien de studie niet tijdens uw dienstverband met Everts wordt afgemaakt dient u altijd het volledige bedrag aan de werkgever terug te betalen. Indien u elders gaat werken, binnen een periode van 3 jaar na het behalen van het diploma (’s ) dient u eveneens het volledige bedrag aan de werkgever terug te betalen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('3913d08b-0272-5248-8ea7-925f6f4fe6fa', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 9, 'tekst', '{"tekst": "Elk jaar worden er functionering - en beoordelingsgesprekken gehouden. Het doel van deze gesprekken is het oplossen van mogelijk knelpunten in uw functioneren, toetsing van opleidingswensen van u en de werkgever. Van alle medewerkers worden de opleidingswensen, die tijdens de gesprekken naar voren zijn gebracht in een verslag vastgelegd. De gespreksonderwerpen met de opmerkingen en de afspraken die tijdens het gesprek gemaakt worden, worden in een verslag vastgelegd en moeten door u worden ondertekend."}'::jsonb, 'Elk jaar worden er functionering - en beoordelingsgesprekken gehouden. Het doel van deze gesprekken is het oplossen van mogelijk knelpunten in uw functioneren, toetsing van opleidingswensen van u en de werkgever. Van alle medewerkers worden de opleidingswensen, die tijdens de gesprekken naar voren zijn gebracht in een verslag vastgelegd. De gespreksonderwerpen met de opmerkingen en de afspraken die tijdens het gesprek gemaakt worden, worden in een verslag vastgelegd en moeten door u worden ondertekend.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('5542981d-eccb-54df-90b8-15d711305e45', 'b236104d-c502-50da-ad0b-ef9a914c4baf', 10, 'tekst', '{"tekst": "Vraag ook bij uw leidinggevende naar de mogelijkheden voor het volgen van opleidingen."}'::jsonb, 'Vraag ook bij uw leidinggevende naar de mogelijkheden voor het volgen van opleidingen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
