insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('558a8103-21f0-55c4-8a1e-315490886621', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 1, 'tekst', '{"tekst": "De loonbetalingen zijn per vier weken en worden per bank uitbetaald."}'::jsonb, 'De loonbetalingen zijn per vier weken en worden per bank uitbetaald.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
