insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('410e97e8-7086-59ad-b3dc-7e803ca0f461', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 4, 'tekst', '{"tekst": "U ontvangt formulieren voor het registreren van de werkuren. Over de manier waarop u de uren  moet registreren op het formulier, zeer gedetailleerd of totaal uren per dag of week, wordt u voor de start van het werk geïnformeerd door uw leidinggevende."}'::jsonb, 'U ontvangt formulieren voor het registreren van de werkuren. Over de manier waarop u de uren  moet registreren op het formulier, zeer gedetailleerd of totaal uren per dag of week, wordt u voor de start van het werk geïnformeerd door uw leidinggevende.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('356a81be-28e5-54c5-abfa-fc0cf819cef0', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 5, 'tekst', '{"tekst": "De registratie van deze uren is van zeer groot belang, niet enkel voor het bepalen van uw salaris, maar ook van belang voor het verkrijgen van werkbare gegevens voor uw collega’s die werkbegrotingen en afrekeningen met de opdrachtgevers moeten maken. U dient de urenregistratie dagelijks in te vullen en iedere vrijdag in te leveren."}'::jsonb, 'De registratie van deze uren is van zeer groot belang, niet enkel voor het bepalen van uw salaris, maar ook van belang voor het verkrijgen van werkbare gegevens voor uw collega’s die werkbegrotingen en afrekeningen met de opdrachtgevers moeten maken. U dient de urenregistratie dagelijks in te vullen en iedere vrijdag in te leveren.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('f2698da7-0159-5d54-bb49-ebabf5de97ae', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 6, 'tekst', '{"tekst": "Mocht het werkbriefje niet op de daarvoor afgesproken tijd ingeleverd, niet correct of niet duidelijk ingevuld zijn, ontvangt u of sturen wij het werkbriefje terug en kunnen wij u salaris over de betreffende week ook niet uitbetalen."}'::jsonb, 'Mocht het werkbriefje niet op de daarvoor afgesproken tijd ingeleverd, niet correct of niet duidelijk ingevuld zijn, ontvangt u of sturen wij het werkbriefje terug en kunnen wij u salaris over de betreffende week ook niet uitbetalen.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('2a614bbb-1e63-55d2-88e2-818331f5d46f', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 7, 'tekst', '{"tekst": "De registratie van deze uren is van zeer groot belang voor het verkrijgen van werkbare gegevens voor uw collega’s die werkbegrotingen en afrekeningen met de opdrachtgevers moeten maken. U dient de urenregistratie dagelijks in te vullen en iedere vrijdag in te leveren."}'::jsonb, 'De registratie van deze uren is van zeer groot belang voor het verkrijgen van werkbare gegevens voor uw collega’s die werkbegrotingen en afrekeningen met de opdrachtgevers moeten maken. U dient de urenregistratie dagelijks in te vullen en iedere vrijdag in te leveren.', 'gepubliceerd', array['extern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('d6303917-3a51-5cd5-8cc0-ede273207625', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 8, 'tekst', '{"tekst": "De werkbrief is de basis voor uw salarisuitbetaling."}'::jsonb, 'De werkbrief is de basis voor uw salarisuitbetaling.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('5c9106c8-a607-5a96-94d0-a1390c5dc004', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 9, 'tekst', '{"tekst": "U bent dus zelf verantwoordelijk dat uw werkbrief tijdig, correct en duidelijk ingevuld, op het kantoor of bij uw leidinggevende aanwezig is!!!"}'::jsonb, 'U bent dus zelf verantwoordelijk dat uw werkbrief tijdig, correct en duidelijk ingevuld, op het kantoor of bij uw leidinggevende aanwezig is!!!', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('336b31ba-8d89-5f01-a3c2-cda1dbecfb97', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 10, 'kop', '{"tekst": "Parkeerkosten", "niveau": "klein"}'::jsonb, 'Parkeerkosten', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('35fb9fa1-1c26-5479-a668-5678d0faf4af', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 11, 'tekst', '{"tekst": "Parkeerkosten binnen Den Haag en aangrenzende gemeenten worden niet vergoed. Buiten Den Haag worden parkeerkosten alleen vergoed wanneer het niet mogelijk is om met een collega mee te rijden. Bij het opstarten van een werk worden hier afspraken over gemaakt met de leidinggevende."}'::jsonb, 'Parkeerkosten binnen Den Haag en aangrenzende gemeenten worden niet vergoed. Buiten Den Haag worden parkeerkosten alleen vergoed wanneer het niet mogelijk is om met een collega mee te rijden. Bij het opstarten van een werk worden hier afspraken over gemaakt met de leidinggevende.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('0b7efdc3-a9d5-53af-8970-0e0e3dac0b65', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 12, 'kop', '{"tekst": "Reiskostenvergoedingen", "niveau": "klein"}'::jsonb, 'Reiskostenvergoedingen', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('a43f96f2-d703-5141-814d-37e6ff94efe4', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 13, 'tekst', '{"tekst": "Indien door projectleider en/of werkgever is bepaald dat er gebruik gemaakt moet worden van een eigen vervoersmiddel zal een vervoermiddelenvergoeding worden betaald. Bij het opstarten van een werk worden hier afspraken over gemaakt met de leidinggevende."}'::jsonb, 'Indien door projectleider en/of werkgever is bepaald dat er gebruik gemaakt moet worden van een eigen vervoersmiddel zal een vervoermiddelenvergoeding worden betaald. Bij het opstarten van een werk worden hier afspraken over gemaakt met de leidinggevende.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('806fc8c0-6f7e-5460-b380-ee907ea2943f', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 14, 'kop', '{"tekst": "Reisuren-vergoedingen", "niveau": "klein"}'::jsonb, 'Reisuren-vergoedingen', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('bab92b6f-056a-5d65-8f9a-fa3bdcb3ba17', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 15, 'tekst', '{"tekst": "Reis uren mogen worden geschreven wanneer er meer dan 1 uur reistijd per dag nodig is. Hierbij wordt uitgegaan van de opgegeven reistijd door een betrouwbare routeplanner. Deze uren worden niet in mindering gebracht op de werkuren. Reisuren worden vergoed met een vast bedrag vergoed van 10 euro bruto per uur en zijn altijd overwerkuren. Hiervan kan in bijzondere gevallen per werk i.o.m. de projectleider van worden afgeweken."}'::jsonb, 'Reis uren mogen worden geschreven wanneer er meer dan 1 uur reistijd per dag nodig is. Hierbij wordt uitgegaan van de opgegeven reistijd door een betrouwbare routeplanner. Deze uren worden niet in mindering gebracht op de werkuren. Reisuren worden vergoed met een vast bedrag vergoed van 10 euro bruto per uur en zijn altijd overwerkuren. Hiervan kan in bijzondere gevallen per werk i.o.m. de projectleider van worden afgeweken.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('b161e9bb-9f43-512a-ba15-e4de614c811a', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 16, 'kop', '{"tekst": "Chauffeursvergoeding", "niveau": "klein"}'::jsonb, 'Chauffeursvergoeding', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('fdfa428b-e8f0-5940-958a-4c811153dfe1', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 17, 'tekst', '{"tekst": "Indien een werknemer als chauffeur van een auto met inzittenden optreedt worden hem ook de"}'::jsonb, 'Indien een werknemer als chauffeur van een auto met inzittenden optreedt worden hem ook de', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('8839a249-0371-5471-9ac2-4bc2b484e54a', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 18, 'tekst', '{"tekst": "eerste 60 minuten reistijd vergoed. De vergoeding voor de chauffeur bedraagt 12,50 euro bruto per"}'::jsonb, 'eerste 60 minuten reistijd vergoed. De vergoeding voor de chauffeur bedraagt 12,50 euro bruto per', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
