insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('bdca4a8f-ec6d-5a18-89a4-bdccd7e54eb7', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 20, 'tekst', '{"tekst": "Indien een werknemer als chauffeur van een auto met inzittenden optreedt worden hem ook de eerste 60 minuten reistijd vergoed. De vergoeding voor de chauffeur bedraagt 12,50 euro bruto per uur vanaf het moment dat er mensen meerijden. Bij het opstarten van een werk worden hier afspraken over gemaakt met de leidinggevende."}'::jsonb, 'Indien een werknemer als chauffeur van een auto met inzittenden optreedt worden hem ook de eerste 60 minuten reistijd vergoed. De vergoeding voor de chauffeur bedraagt 12,50 euro bruto per uur vanaf het moment dat er mensen meerijden. Bij het opstarten van een werk worden hier afspraken over gemaakt met de leidinggevende.', 'gepubliceerd', array['extern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('ae3ef8ad-1c6f-501d-805e-fe61931264a3', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 21, 'tekst', '{"tekst": "Reiskosten-, reisuren- en chauffeursvergoedingen worden berekend van het vestigingsadres in Leidschendam, niet vanaf het thuisadres."}'::jsonb, 'Reiskosten-, reisuren- en chauffeursvergoedingen worden berekend van het vestigingsadres in Leidschendam, niet vanaf het thuisadres.', 'gepubliceerd', array['extern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('a2797012-ccab-5533-8a72-0c76935ca6fd', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 22, 'kop', '{"tekst": "Overwerk", "niveau": "klein"}'::jsonb, 'Overwerk', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('54e317f6-244d-559c-9506-fd80043be942', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 23, 'tekst', '{"tekst": "Overwerk wordt gerekend vanaf een half uur na einde werktijd. Overwerk wordt niet uitbetaald maar kan op een later moment worden opgenomen."}'::jsonb, 'Overwerk wordt gerekend vanaf een half uur na einde werktijd. Overwerk wordt niet uitbetaald maar kan op een later moment worden opgenomen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('4bf7611e-e50b-5bee-ade2-14a7d0c708de', '6fbb27ec-2feb-5085-bbf3-a24d524a507a', 24, 'tekst', '{"tekst": "In perioden waarin er veel werk is (vaak is dit in de maanden april tot en met oktober), bouw je de overuren op. In perioden waarin er minder werk is (vaak van november tot en met maart), kunnen overuren worden gebruikt om de werknemer minder of kortere dagen te laten werken."}'::jsonb, 'In perioden waarin er veel werk is (vaak is dit in de maanden april tot en met oktober), bouw je de overuren op. In perioden waarin er minder werk is (vaak van november tot en met maart), kunnen overuren worden gebruikt om de werknemer minder of kortere dagen te laten werken.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_secties (id, slug, titel, volgorde, soort, status, zichtbaar_voor, verborgen_voor) values ('d33425c7-392e-5183-9682-60ce95fa129b', 'kleding', 'Kleding', 8, 'hoofdstuk', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('8c3c67c3-1b42-59ae-bfda-8c000212bdc0', 'd33425c7-392e-5183-9682-60ce95fa129b', 1, 'tekst', '{"tekst": "Medewerkers van Everts ontvangen veilige werkkleding. Deze werkkleding ziet er goed ogend en representatief uit. Deze werkkleding moet het veilig werken bevorderen en dient natuurlijk ook om uw eigen kleding te beschermen."}'::jsonb, 'Medewerkers van Everts ontvangen veilige werkkleding. Deze werkkleding ziet er goed ogend en representatief uit. Deze werkkleding moet het veilig werken bevorderen en dient natuurlijk ook om uw eigen kleding te beschermen.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('43c8605f-ed1f-55d0-84e1-e7b76e2c131a', 'd33425c7-392e-5183-9682-60ce95fa129b', 2, 'tekst', '{"tekst": "U bent verplicht deze werkkleding tijdens uw werk te dragen. Indien u geen werkkleding bij de start van het werk bij u heeft, of uw werkkleding is sterk vervuild, kan u naar huis gestuurd worden om nieuwe werkkleding te halen. Het transport naar huis moet u zelf op eigen kosten regelen en de verleturen zullen op uw salaris in mindering gebracht worden."}'::jsonb, 'U bent verplicht deze werkkleding tijdens uw werk te dragen. Indien u geen werkkleding bij de start van het werk bij u heeft, of uw werkkleding is sterk vervuild, kan u naar huis gestuurd worden om nieuwe werkkleding te halen. Het transport naar huis moet u zelf op eigen kosten regelen en de verleturen zullen op uw salaris in mindering gebracht worden.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('4af6e082-e686-5f5d-bf14-26fa1c767210', 'd33425c7-392e-5183-9682-60ce95fa129b', 3, 'tekst', '{"tekst": "Flexkrachten bij Everts ontvangen veilige werkkleding. Deze werkkleding ziet er goed ogend en representatief uit. Deze werkkleding moet het veilig werken bevorderen en dient natuurlijk ook om uw eigen kleding te beschermen."}'::jsonb, 'Flexkrachten bij Everts ontvangen veilige werkkleding. Deze werkkleding ziet er goed ogend en representatief uit. Deze werkkleding moet het veilig werken bevorderen en dient natuurlijk ook om uw eigen kleding te beschermen.', 'gepubliceerd', array['extern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('30b7a4c6-77a6-53d2-a1e8-429b02671de6', 'd33425c7-392e-5183-9682-60ce95fa129b', 4, 'tekst', '{"tekst": "U bent verplicht deze werkkleding tijdens uw werk te dragen. Indien u geen werkkleding bij de start van het werk bij u heeft, of uw werkkleding is sterk vervuild, kan u naar huis gestuurd worden om nieuwe werkkleding te halen. Het transport naar huis moet u zelf op eigen kosten regelen en de verleturen zullen niet betaald worden."}'::jsonb, 'U bent verplicht deze werkkleding tijdens uw werk te dragen. Indien u geen werkkleding bij de start van het werk bij u heeft, of uw werkkleding is sterk vervuild, kan u naar huis gestuurd worden om nieuwe werkkleding te halen. Het transport naar huis moet u zelf op eigen kosten regelen en de verleturen zullen niet betaald worden.', 'gepubliceerd', array['extern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('9a7ee04c-79b7-5630-a605-005f6a3079db', 'd33425c7-392e-5183-9682-60ce95fa129b', 5, 'tekst', '{"tekst": "Bij sterk vervuilende werkzaamheden, of werkzaamheden waarbij slijtage van de werkkleding bovenmatig is, zal nieuwe werkkleding beschikbaar gesteld worden. Dit ter beoordeling van uw leidinggevende."}'::jsonb, 'Bij sterk vervuilende werkzaamheden, of werkzaamheden waarbij slijtage van de werkkleding bovenmatig is, zal nieuwe werkkleding beschikbaar gesteld worden. Dit ter beoordeling van uw leidinggevende.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('98e75291-58d5-5e15-808b-6e5e3ded0227', 'd33425c7-392e-5183-9682-60ce95fa129b', 6, 'tekst', '{"tekst": "U ontvangt geen vergoeding voor het aanschaffen van werkkleding. Everts verstrekt de werkkleding aan u. De kleding blijft eigendom van Everts en dient bij einde dienstverband ingeleverd te worden."}'::jsonb, 'U ontvangt geen vergoeding voor het aanschaffen van werkkleding. Everts verstrekt de werkkleding aan u. De kleding blijft eigendom van Everts en dient bij einde dienstverband ingeleverd te worden.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
