insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('0c56c21e-1d81-5714-9978-a0cf861b0f12', '861f7b01-7968-5de6-8f85-c9c8426bd5f8', 1, 'tekst', '{"tekst": "Verder bent u verplicht, de u ter beschikking gestelde Persoonlijke Beschermingsmiddelen, zoals een veiligheidsbril, veiligheidshelm, veiligheidsschoenen, veiligheidslaarzen, veiligheidshandschoenen enzovoort goed te onderhouden en in voorkomende situaties te dragen."}'::jsonb, 'Verder bent u verplicht, de u ter beschikking gestelde Persoonlijke Beschermingsmiddelen, zoals een veiligheidsbril, veiligheidshelm, veiligheidsschoenen, veiligheidslaarzen, veiligheidshandschoenen enzovoort goed te onderhouden en in voorkomende situaties te dragen.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
