insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('f7701437-fcd3-5c46-96ab-18be2644e78f', 'e67807d8-142e-5e53-b310-f47f25b963ba', 2, 'tekst', '{"tekst": "Iedereen is verantwoordelijk voor een opgeruimde werkplaats. Alles heeft een eigen plek en moet daar ook opgeruimd worden. Als je niet weet waar iets opgeruimd moet worden, vraag dit na bij je leidinggevende en leg dit niet zomaar ergens in de werkplaats, dit hindert collega’s."}'::jsonb, 'Iedereen is verantwoordelijk voor een opgeruimde werkplaats. Alles heeft een eigen plek en moet daar ook opgeruimd worden. Als je niet weet waar iets opgeruimd moet worden, vraag dit na bij je leidinggevende en leg dit niet zomaar ergens in de werkplaats, dit hindert collega’s.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
