insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('38583def-aa67-59d0-b2f9-e415d9bbbd59', '8a8f8adf-e635-5687-9416-2abe05e00cab', 1, 'tekst', '{"tekst": "Als je gereedschap en/of materieel krijgt ben je daar ten alle tijden verantwoordelijk voor."}'::jsonb, 'Als je gereedschap en/of materieel krijgt ben je daar ten alle tijden verantwoordelijk voor.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('2930e593-afd8-534b-a600-9923796d0024', '8a8f8adf-e635-5687-9416-2abe05e00cab', 2, 'tekst', '{"tekst": "Je zorgt dat hier netjes mee om wordt gegaan en dat dit jaarlijks gekeurd wordt. De keuring worden centraal uitgevoerd in de werkplaats. Gereedschap en materieel wat niet goedgekeurd wordt kan gerepareerd worden en anders moet deze vervangen worden."}'::jsonb, 'Je zorgt dat hier netjes mee om wordt gegaan en dat dit jaarlijks gekeurd wordt. De keuring worden centraal uitgevoerd in de werkplaats. Gereedschap en materieel wat niet goedgekeurd wordt kan gerepareerd worden en anders moet deze vervangen worden.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('78e77b9b-b420-5af7-8c9f-42909c15d723', '8a8f8adf-e635-5687-9416-2abe05e00cab', 3, 'tekst', '{"tekst": "Timmermannen dienen al het benodigde handgereedschap zelf aan te schaffen, te onderhouden en te vervangen wanneer nodig."}'::jsonb, 'Timmermannen dienen al het benodigde handgereedschap zelf aan te schaffen, te onderhouden en te vervangen wanneer nodig.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
