insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('71726d98-e7c8-5d9e-b9d7-2e6f61f4e3a5', '8a8f8adf-e635-5687-9416-2abe05e00cab', 5, 'tekst', '{"tekst": "Onderling uitlenen kan nodig zijn om je collega’s te helpen hun werk uit te voeren. Bedenk hierbij goed dat de eigenaar eindverantwoordelijk blijft en moet zijn collega’s dus controleren of ze net zo zorgvuldig mee omgaan als dat ze zelf doen."}'::jsonb, 'Onderling uitlenen kan nodig zijn om je collega’s te helpen hun werk uit te voeren. Bedenk hierbij goed dat de eigenaar eindverantwoordelijk blijft en moet zijn collega’s dus controleren of ze net zo zorgvuldig mee omgaan als dat ze zelf doen.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
