insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('994417d6-3eb7-5c2a-9c8c-0d1444a96da1', '8f739874-3d69-5952-a1dd-eae133080d95', 3, 'tekst', '{"tekst": "Wanneer je ziet dat dit een keuring niet zou doorstaan, geef dit aan bij je leidinggevende en zorg dat dit herkenbaar is aangegeven zodat collega’s dit niet per ongeluk kunnen gebruiken. Probeer uiteraard eerst dit zelf te repareren wanneer dit mogelijk is."}'::jsonb, 'Wanneer je ziet dat dit een keuring niet zou doorstaan, geef dit aan bij je leidinggevende en zorg dat dit herkenbaar is aangegeven zodat collega’s dit niet per ongeluk kunnen gebruiken. Probeer uiteraard eerst dit zelf te repareren wanneer dit mogelijk is.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_secties (id, slug, titel, volgorde, soort, status, zichtbaar_voor, verborgen_voor) values ('92d2f8fa-eb00-558f-90ee-e1cd14cb00e5', 'schade', 'Schade', 14, 'hoofdstuk', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('8c6baf71-b161-577e-af5a-37ae9616696a', '92d2f8fa-eb00-558f-90ee-e1cd14cb00e5', 1, 'tekst', '{"tekst": "Als er schade ontstaat tijdens het verrichten van werkzaamheden, dient u dit direct mondeling te melden bij uw leidinggevende. Door uw snelle melding kunnen schades en ergernissen bij de klant en intern bij Everts tot een minimum beperkt worden."}'::jsonb, 'Als er schade ontstaat tijdens het verrichten van werkzaamheden, dient u dit direct mondeling te melden bij uw leidinggevende. Door uw snelle melding kunnen schades en ergernissen bij de klant en intern bij Everts tot een minimum beperkt worden.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_secties (id, slug, titel, volgorde, soort, status, zichtbaar_voor, verborgen_voor) values ('dd2a5d4f-f289-5aa9-b171-f1e337000efd', 'auto-of-bus', 'Auto of bus', 15, 'hoofdstuk', 'gepubliceerd', array['voertuig', 'kantoor']::text[], array['extern']::text[]) on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('48f58b7d-b59d-5bcd-8842-f3894f4d6c49', 'dd2a5d4f-f289-5aa9-b171-f1e337000efd', 1, 'lijst', '{"stijl": "bullet", "items": ["Een auto van de zaak is een secundaire arbeidsvoorwaarde en niet voor iedereen vanzelfsprekend. Een werkbus of auto kan noodzakelijk zijn voor het uitvoeren van de functie.", "Wanneer er bijtelling wordt betaald over een auto of bus mag deze ook privé gebruikt worden. Dit moet altijd met toestemming van de bedrijfsdirecteur en is geen vast recht. Wanneer er geen bijtelling betaald wordt kan de bedrijfsdirecteur toestemming geven voor het gebruik van 500 privé-kilometers per jaar. Als er gekozen wordt om geen bijtelling te betalen is de gebruiker van de auto of bus zelf verantwoordelijk voor het bijhouden van een sluitende kilometerregistratie en “een Verklaring geen privégebruik auto” van de Belastingdienst.", "Alle auto’s zijn voorzien van een tracker t.b.v. de belastingdienst. In de bijbehorende app kan je, in het geval van privégebruik, per rit aangeven of het zakelijke of privéritten betreft. Dit is je eigen verantwoordelijkheid.", "Elke auto heeft een tankpas voor binnen Nederland. Daarmee kan getankt worden en benodigde materialen voor onderhoud van de auto. Ook kan daarmee gebruik gemaakt worden van de wasstraat.", "De gebruiker is verantwoordelijk voor reparaties, schoon houden en het onderhoud van het voertuig.", "Schade aan het voertuig kan onverhoopt gebeuren. Daarom wordt er 1x per jaar het eigen risico betaald die benodigd is om het voertuig weer representatief te herstellen. Indien er vaker schade gemaakt wordt, wordt het eigen risico ingehouden op het salaris van de gebruiker. Hier is een uitzondering op, namelijk wanneer de schade wordt gemaakt onder werktijd en deze correct gemeld wordt. Wanneer er schade wordt gemaakt tijdens privégebruik zal dit ten kosten van de gebruiker komen. Schade wordt altijd gemeld door middel van een schadeformulier, ook als er geen andere partijen betrokken zijn bij de schade.", "Verkeersboetes worden ter informatie per mail verzonden en door het bedrijf betaald. In de eerst volgende maand wordt het boetebedrag van het loon ingehouden. De boete wordt in het geval van een leaseauto door de leasemaatschappij verhoogd met administratiekosten.", "Alle auto’s zijn voorzien van het bedrijfslogo. Rij dus netjes!", "Iedereen met een auto/bus van de zaak heeft een autocontract afgesloten, daarin staan de verdere details omschreven."]}'::jsonb, 'Een auto van de zaak is een secundaire arbeidsvoorwaarde en niet voor iedereen vanzelfsprekend. Een werkbus of auto kan noodzakelijk zijn voor het uitvoeren van de functie. Wanneer er bijtelling wordt betaald over een auto of bus mag deze ook privé gebruikt worden. Dit moet altijd met toestemming van de bedrijfsdirecteur en is geen vast recht. Wanneer er geen bijtelling betaald wordt kan de bedrijfsdirecteur toestemming geven voor het gebruik van 500 privé-kilometers per jaar. Als er gekozen wordt om geen bijtelling te betalen is de gebruiker van de auto of bus zelf verantwoordelijk voor het bijhouden van een sluitende kilometerregistratie en “een Verklaring geen privégebruik auto” van de Belastingdienst. Alle auto’s zijn voorzien van een tracker t.b.v. de belastingdienst. In de bijbehorende app kan je, in het geval van privégebruik, per rit aangeven of het zakelijke of privéritten betreft. Dit is je eigen verantwoordelijkheid. Elke auto heeft een tankpas voor binnen Nederland. Daarmee kan getankt worden en benodigde materialen voor onderhoud van de auto. Ook kan daarmee gebruik gemaakt worden van de wasstraat. De gebruiker is verantwoordelijk voor reparaties, schoon houden en het onderhoud van het voertuig. Schade aan het voertuig kan onverhoopt gebeuren. Daarom wordt er 1x per jaar het eigen risico betaald die benodigd is om het voertuig weer representatief te herstellen. Indien er vaker schade gemaakt wordt, wordt het eigen risico ingehouden op het salaris van de gebruiker. Hier is een uitzondering op, namelijk wanneer de schade wordt gemaakt onder werktijd en deze correct gemeld wordt. Wanneer er schade wordt gemaakt tijdens privégebruik zal dit ten kosten van de gebruiker komen. Schade wordt altijd gemeld door middel van een schadeformulier, ook als er geen andere partijen betrokken zijn bij de schade. Verkeersboetes worden ter informatie per mail verzonden en door het bedrijf betaald. In de eerst volgende maand wordt het boetebedrag van het loon ingehouden. De boete wordt in het geval van een leaseauto door de leasemaatschappij verhoogd met administratiekosten. Alle auto’s zijn voorzien van het bedrijfslogo. Rij dus netjes! Iedereen met een auto/bus van de zaak heeft een autocontract afgesloten, daarin staan de verdere details omschreven.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('e628c201-6e70-5376-8282-7ddbb5d53264', 'dd2a5d4f-f289-5aa9-b171-f1e337000efd', 2, 'kop', '{"tekst": "Functies en bijbehorende auto’s", "niveau": "klein"}'::jsonb, 'Functies en bijbehorende auto’s', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
