insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('177719bb-42ed-5097-ace0-f6563eae94c7', '529ff2be-b088-5d6a-a826-b82538c165fd', 1, 'tekst', '{"tekst": "Welk rijbewijs je moet hebben voor uw aanhanger, caravan of oplegger hangt af van de toegestane maximale massa. Dit is het lege gewicht plus het maximale laadvermogen."}'::jsonb, 'Welk rijbewijs je moet hebben voor uw aanhanger, caravan of oplegger hangt af van de toegestane maximale massa. Dit is het lege gewicht plus het maximale laadvermogen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('b030ea4b-a37b-57d4-9dac-3be635468fb4', '529ff2be-b088-5d6a-a826-b82538c165fd', 2, 'tekst', '{"tekst": "Een aanhanger kan bijvoorbeeld een toegestane maximale massa van 750 kilo hebben. Als de aanhanger zelf 150 kilo weegt (lege gewicht), dan mag er nog 600 kilo aan lading bij (laadvermogen). Het gaat dus niet om het daadwerkelijke gewicht."}'::jsonb, 'Een aanhanger kan bijvoorbeeld een toegestane maximale massa van 750 kilo hebben. Als de aanhanger zelf 150 kilo weegt (lege gewicht), dan mag er nog 600 kilo aan lading bij (laadvermogen). Het gaat dus niet om het daadwerkelijke gewicht.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
