insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('64b0d31e-e55d-5149-88b2-d47d641ba30a', '529ff2be-b088-5d6a-a826-b82538c165fd', 4, 'lijst', '{"stijl": "bullet", "items": ["een aanhanger trekken van maximaal 750 kilo (lege gewicht + laadvermogen);", "een aanhanger trekken van meer dan 750 kilo als de auto en de aanhanger samen niet boven de 3.500 kilo (lege gewicht + laadvermogen) uitkomen."]}'::jsonb, 'een aanhanger trekken van maximaal 750 kilo (lege gewicht + laadvermogen); een aanhanger trekken van meer dan 750 kilo als de auto en de aanhanger samen niet boven de 3.500 kilo (lege gewicht + laadvermogen) uitkomen.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
