insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('9f8cd93b-fdc6-5111-b148-6c869efb9d73', 'dd97af3e-5b14-5149-bef2-189b6854c6da', 1, 'tekst', '{"tekst": "Het gebruik van de mobiele telefoon, is voor velen binnen Everts noodzakelijk om het werk goed en veilig te kunnen uitvoeren."}'::jsonb, 'Het gebruik van de mobiele telefoon, is voor velen binnen Everts noodzakelijk om het werk goed en veilig te kunnen uitvoeren.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('ee21dd26-a8db-52e5-9600-386aae338b41', 'dd97af3e-5b14-5149-bef2-189b6854c6da', 2, 'tekst', '{"tekst": "Onjuist omgaan met de mobiele telefoon kost tijd en kan het veilig werken, daarmee uw veiligheid en de veiligheid van uw collega’s beïnvloeden."}'::jsonb, 'Onjuist omgaan met de mobiele telefoon kost tijd en kan het veilig werken, daarmee uw veiligheid en de veiligheid van uw collega’s beïnvloeden.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('968e1088-fbc8-5d56-a6ae-c0bae3a85866', 'dd97af3e-5b14-5149-bef2-189b6854c6da', 3, 'tekst', '{"tekst": "Bovendien wekt het onnodig gebruik van de mobiele telefoon veel ergernis op bij de opdrachtgevers, de klanten van Everts en uw collega’s."}'::jsonb, 'Bovendien wekt het onnodig gebruik van de mobiele telefoon veel ergernis op bij de opdrachtgevers, de klanten van Everts en uw collega’s.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('a39eb130-327f-5fa3-800b-42e8b3823fd2', 'dd97af3e-5b14-5149-bef2-189b6854c6da', 4, 'lijst', '{"stijl": "bullet", "items": ["Een abonnement is afgesloten voor normaal gebruik, zowel zakelijk als privé. Excessief gebruik zoals overmatig data gebruik of veel bellen in het buitenland wordt van het salaris ingehouden.", "Het verschaffen van een mobiele telefoon gebeurd op basis van de noodzaak bij de functie en te bepalen door leidinggevende.", "Uitvoerend personeel heeft € 150,00 per jaar te besteden aan een telefoon", "UTA personeel heeft € 250,00 per jaar te besteden aan een telefoon.", "Wanneer er een duurdere telefoon gewenst is kan dit door de werknemer aangevuld worden.", "Bij het verschaffen van een telefoon wordt niet verwacht dat men buiten werktijd direct beschikbaar is. Wel mag er verwacht worden dat men op beschikbare momenten controleert of het noodzakelijk is om contact te hebben buiten werktijd, dit is gekoppeld aan de functie waarbij een telefoon noodzakelijk is.", "Personeel wat geen telefoon van de zaak is verschaft wordt verwacht onder werktijd bereikbaar te zijn op de privé mobiele telefoon. Wanneer aantoonbaar is dat er extra kosten zijn gemaakt voor het gebruik van de eigen telefoon voor werkdoeleinden wordt dit vergoed.", "De eigen mobiele telefoon mag onder werktijd niet gebruikt worden voor privé doeleinden."]}'::jsonb, 'Een abonnement is afgesloten voor normaal gebruik, zowel zakelijk als privé. Excessief gebruik zoals overmatig data gebruik of veel bellen in het buitenland wordt van het salaris ingehouden. Het verschaffen van een mobiele telefoon gebeurd op basis van de noodzaak bij de functie en te bepalen door leidinggevende. Uitvoerend personeel heeft € 150,00 per jaar te besteden aan een telefoon UTA personeel heeft € 250,00 per jaar te besteden aan een telefoon. Wanneer er een duurdere telefoon gewenst is kan dit door de werknemer aangevuld worden. Bij het verschaffen van een telefoon wordt niet verwacht dat men buiten werktijd direct beschikbaar is. Wel mag er verwacht worden dat men op beschikbare momenten controleert of het noodzakelijk is om contact te hebben buiten werktijd, dit is gekoppeld aan de functie waarbij een telefoon noodzakelijk is. Personeel wat geen telefoon van de zaak is verschaft wordt verwacht onder werktijd bereikbaar te zijn op de privé mobiele telefoon. Wanneer aantoonbaar is dat er extra kosten zijn gemaakt voor het gebruik van de eigen telefoon voor werkdoeleinden wordt dit vergoed. De eigen mobiele telefoon mag onder werktijd niet gebruikt worden voor privé doeleinden.', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_secties (id, slug, titel, volgorde, soort, status, zichtbaar_voor, verborgen_voor) values ('69659962-1619-532f-a7bb-21a4ef0b3a0b', 'verlof', 'Verlof', 18, 'hoofdstuk', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('f549ebe2-9c22-5120-9d42-3e066bc2189a', '69659962-1619-532f-a7bb-21a4ef0b3a0b', 1, 'kop', '{"tekst": "Verlof aanvragen", "niveau": "klein"}'::jsonb, 'Verlof aanvragen', 'gepubliceerd', '{}', '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('1652b226-f9a5-5d34-8f79-c713f13a0140', '69659962-1619-532f-a7bb-21a4ef0b3a0b', 2, 'lijst', '{"stijl": "bullet", "items": ["Afspraken met dokter, tandarts e.d. dient u 2 à 3 dagen vooraf met Everts af te stemmen en op een zodanig tijdstip te kiezen dat de functie uitoefening zo min mogelijk wordt belemmerd.", "Een vrije dag moeten minimaal 2 weken van te voren worden aangevraagd.", "Meerdere dagen tot een week vrij minimaal een maand.", "Een vakantie van langer dan een week minimaal 2 maanden van te voren.", "Zomervakantie moet uiterlijk eind maart bekend zijn. Maximaal 3 weken aaneengesloten vakantie. Langere vakantie moet speciaal aangevraagd, besproken en goedgekeurd worden. Maximaal 1x per 5 jaar."]}'::jsonb, 'Afspraken met dokter, tandarts e.d. dient u 2 à 3 dagen vooraf met Everts af te stemmen en op een zodanig tijdstip te kiezen dat de functie uitoefening zo min mogelijk wordt belemmerd. Een vrije dag moeten minimaal 2 weken van te voren worden aangevraagd. Meerdere dagen tot een week vrij minimaal een maand. Een vakantie van langer dan een week minimaal 2 maanden van te voren. Zomervakantie moet uiterlijk eind maart bekend zijn. Maximaal 3 weken aaneengesloten vakantie. Langere vakantie moet speciaal aangevraagd, besproken en goedgekeurd worden. Maximaal 1x per 5 jaar.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('2cd21923-8234-5b8e-929d-9cf73d452989', '69659962-1619-532f-a7bb-21a4ef0b3a0b', 3, 'lijst', '{"stijl": "bullet", "items": ["Afspraken met dokter, tandarts e.d. dient u 2 à 3 dagen vooraf met Everts af te stemmen en op een zodanig tijdstip te kiezen dat de functie uitoefening zo min mogelijk wordt belemmerd.", "Een vrije dag moeten minimaal 2 weken van te voren worden aangevraagd.", "Meerdere dagen tot een week vrij minimaal een maand.", "Een vakantie van langer dan een week minimaal 2 maanden van te voren.", "Zomervakantie moet uiterlijk eind maart bekend zijn. Maximaal 3 weken aaneengesloten vakantie. Langere vakantie moet speciaal aangevraagd, besproken en goedgekeurd worden."]}'::jsonb, 'Afspraken met dokter, tandarts e.d. dient u 2 à 3 dagen vooraf met Everts af te stemmen en op een zodanig tijdstip te kiezen dat de functie uitoefening zo min mogelijk wordt belemmerd. Een vrije dag moeten minimaal 2 weken van te voren worden aangevraagd. Meerdere dagen tot een week vrij minimaal een maand. Een vakantie van langer dan een week minimaal 2 maanden van te voren. Zomervakantie moet uiterlijk eind maart bekend zijn. Maximaal 3 weken aaneengesloten vakantie. Langere vakantie moet speciaal aangevraagd, besproken en goedgekeurd worden.', 'gepubliceerd', array['extern']::text[], '{}') on conflict (id) do nothing;
