insert into public.personeelshandboek_blokken (id, sectie_id, volgorde, type, inhoud, zoektekst, status, zichtbaar_voor, verborgen_voor) values ('bc57da92-b006-5a70-99ca-4ae99b8e2066', '12ed8e8e-8e9f-540f-b527-8dcb859115c0', 1, 'tekst', '{"tekst": "Remplooi verzorgt de verzuimbegeleiding en de Arbo-dienstverlening voor Everts.  Remplooi treedt in alle Arbo- en verzuimgevallen op namens Everts. Werknemers dienen verzuim door te geven aan Remplooi en aan de direct leidinggevende. Wijzigingen in het verzuim en de herstelmeldingen dienen door de werknemer aan Remplooi doorgegeven te worden en aan de direct leidinggevende."}'::jsonb, 'Remplooi verzorgt de verzuimbegeleiding en de Arbo-dienstverlening voor Everts.  Remplooi treedt in alle Arbo- en verzuimgevallen op namens Everts. Werknemers dienen verzuim door te geven aan Remplooi en aan de direct leidinggevende. Wijzigingen in het verzuim en de herstelmeldingen dienen door de werknemer aan Remplooi doorgegeven te worden en aan de direct leidinggevende.', 'gepubliceerd', array['intern']::text[], '{}') on conflict (id) do nothing;
